@app.get("/static/img/{filename}")
def serve_svg(filename: str):
    if filename in SVG_ICONS:
        return Response(content=SVG_ICONS[filename], media_type="image/svg+xml")
    raise HTTPException(status_code=404, detail="Icon not found")

class ExtractRequest(BaseModel):
    url: str

def sanitize_filename(name: str) -> str:
    clean = re.sub(r'[\\/*?:"<>|]', "", name)
    return clean[:120].strip() or "video"

def get_video_info(url: str):
    ydl_opts = {
        'quiet': True,
        'no_warnings': True,
        'skip_download': True,
    }
    with yt_dlp.YoutubeDL(ydl_opts) as ydl:
        info = ydl.extract_info(url, download=False)
        if not info:
            raise ValueError("Could not retrieve video information.")
        title = info.get('title', 'Video')
        thumbnail = info.get('thumbnail')
        duration = info.get('duration')
        extractor = info.get('extractor_key', 'Generic').replace("IE", "").capitalize()
        formats = info.get('formats', [])
        
        if duration:
            m, s = divmod(int(duration), 60)
            h, m = divmod(m, 60)
            duration_str = f"{h:d}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"
        else:
            duration_str = ""

        options = []
        seen_heights = set()
        for f in formats:
            f_id = f.get('format_id')
            ext = f.get('ext')
            height = f.get('height')
            vcodec = f.get('vcodec')
            acodec = f.get('acodec')
            filesize = f.get('filesize') or f.get('filesize_approx')
            size_str = ""
            if filesize:
                mb = filesize / (1024 * 1024)
                size_str = f"{mb:.1f} MB" if mb >= 1 else f"{filesize / 1024:.0f} KB"

            if vcodec != 'none' and height and height >= 144:
                quality_label = f"MP4 {height}p"
                if height >= 2160: quality_label = f"MP4 4K ({height}p)"
                elif height >= 1440: quality_label = f"MP4 2K ({height}p)"
                elif height >= 1080: quality_label = f"MP4 1080p (Full HD)"
                elif height >= 720: quality_label = f"MP4 720p (HD)"
                elif height >= 480: quality_label = f"MP4 480p"
                elif height >= 360: quality_label = f"MP4 360p"

                if height not in seen_heights:
                    seen_heights.add(height)
                    options.append({
                        'format_id': f_id,
                        'height': height,
                        'quality': quality_label,
                        'ext': 'mp4',
                        'resolution': f"{f.get('width', '')}x{height}",
                        'size': size_str,
                        'has_audio': (acodec != 'none'),
                        'is_audio': False
                    })

        options.sort(key=lambda x: x['height'], reverse=True)
        if not options:
            options.append({'format_id': 'best', 'height': 720, 'quality': 'MP4 Best Quality', 'ext': 'mp4', 'resolution': 'Default', 'size': '', 'has_audio': True, 'is_audio': False})
        options.append({'format_id': 'bestaudio', 'height': 0, 'quality': 'Audio MP3 (320kbps)', 'ext': 'mp3', 'resolution': 'Audio Only', 'size': '', 'has_audio': True, 'is_audio': True})

        return {'success': True, 'title': title, 'thumbnail': thumbnail, 'duration': duration_str, 'platform': extractor, 'url': url, 'options': options}

