@app.post("/api/extract")
async def extract_api(payload: ExtractRequest):
    url = payload.url.strip()
    if not url: return JSONResponse({"success": False, "error": "Please enter a valid video link."}, status_code=400)
    try:
        loop = asyncio.get_event_loop()
        info = await loop.run_in_executor(None, get_video_info, url)
        return JSONResponse(info)
    except Exception as e:
        return JSONResponse({"success": False, "error": f"Failed to fetch video: {str(e)}"}, status_code=500)

@app.post("/savefrom.php")
async def savefrom_form_endpoint(sf_url: str = Form(...)):
    url = sf_url.strip()
    if not url: return JSONResponse({"success": False, "error": "Please enter a video URL."}, status_code=400)
    try:
        loop = asyncio.get_event_loop()
        info = await loop.run_in_executor(None, get_video_info, url)
        return JSONResponse(info)
    except Exception as e:
        return JSONResponse({"success": False, "error": str(e)}, status_code=500)

@app.get("/api/download")
async def download_video(
    url: str = Query(..., description="Video source URL"),
    format_id: Optional[str] = Query("best", description="yt-dlp format id or height"),
    is_audio: bool = Query(False, description="Convert to MP3 audio only"),
    title: Optional[str] = Query("video", description="Video title for download")
):
    safe_title = sanitize_filename(title)
    temp_dir = tempfile.mkdtemp(prefix="savefrom_")
    if is_audio:
        out_template = os.path.join(temp_dir, f"{safe_title}.%(ext)s")
        ydl_opts = {
            'format': 'bestaudio/best',
            'outtmpl': out_template,
            'postprocessors': [{'key': 'FFmpegExtractAudio', 'preferredcodec': 'mp3', 'preferredquality': '192'}],
            'quiet': True, 'no_warnings': True,
        }
    else:
        out_template = os.path.join(temp_dir, f"{safe_title}.%(ext)s")
        if format_id and format_id.isdigit(): fmt_str = f"bestvideo[height<={format_id}]+bestaudio/best[height<={format_id}]/best"
        elif format_id and format_id != "best": fmt_str = f"{format_id}+bestaudio/best"
        else: fmt_str = "bestvideo+bestaudio/best"
        ydl_opts = {'format': fmt_str, 'outtmpl': out_template, 'merge_output_format': 'mp4', 'quiet': True, 'no_warnings': True}

    loop = asyncio.get_event_loop()
    try:
        await loop.run_in_executor(None, lambda: yt_dlp.YoutubeDL(ydl_opts).download([url]))
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Download extraction error: {str(e)}")

    created_files = os.listdir(temp_dir)
    if not created_files: raise HTTPException(status_code=500, detail="Downloaded file could not be created.")
    final_filepath = os.path.join(temp_dir, created_files[0])
    file_size = os.path.getsize(final_filepath)
    actual_filename = os.path.basename(final_filepath)

    async def iterfile():
        try:
            with open(final_filepath, "rb") as f:
                while chunk := f.read(1024 * 128): yield chunk
        finally:
            try:
                if os.path.exists(final_filepath): os.remove(final_filepath)
                if os.path.exists(temp_dir): os.rmdir(temp_dir)
            except Exception: pass

    encoded_filename = quote(actual_filename)
    headers = {
        "Content-Disposition": f"attachment; filename*=UTF-8''{encoded_filename}",
        "Content-Length": str(file_size),
        "Content-Type": "audio/mpeg" if is_audio else "video/mp4",
        "Accept-Ranges": "bytes"
    }
    return StreamingResponse(iterfile(), headers=headers)

