    try:
        uvicorn.run('app:app', host=host, port=port, reload=False)
    except Exception as e:
        print(f'[!] Port {port} unavailable ({e}). Falling back to port 8000...')
        uvicorn.run('app:app', host=host, port=8000, reload=False)
